// #0532cb מסך גורמים מקצועיים קבועים — шаг 3 мастера /onboarding (тексты по Figma 1141:1764) и касание «•••» → «הסרה» на iPhone (WebKit).
// Кейсы: .qa/tests/onboarding-professionals/OPR-10..OPR-12. План: specs/onboarding-professionals.md.
// ДАННЫЕ НЕ МЕНЯЮТСЯ: «сервер в памяти» (../onboarding-wizard/wizard-mock.ts) — POST company_profiles перехватываются и на сервер
// не уходят, прочие записи в Supabase прерываются (blockedWrites = 0). Поэтому без @data и без риска last-write-wins (#318805).
import { test, expect } from '@playwright/test';
import { authState } from '../helpers/tenderflow';
import { clickAndSaveTaqo, mockWizardServer } from '../onboarding-wizard/wizard-mock';

const NEXT = 'המשך לשלב הבא';
// Тексты — как отдаёт staging (в «עו״ד» / «רו״ח» — типографские гершаим ״; в Figma ASCII-кавычка ").
const LEAD = 'הגדרת הגורמים המאשרים והחותמים של החברה. בעת הכנת מכרז, TAQO תשלח להם קישור מאובטח לחתימה או להעלאת אישורים בלחיצת כפתור — ללא צורך בפתיחת משתמש במערכת.';
const HOW_1 = 'אין צורך ברישיון משתמש: גורמים חיצוניים (עו״ד, רו״ח, סוכן ביטוח) אינם זקוקים לחשבון ב-TAQO.';
const HOW_2 = 'כאשר נדרש אישור או אימות תצהיר, נשלח אליהם קישור חד-פעמי מאובטח, והמסמך החתום נקלט אוטומטית בכספת ובתיק ההגשה.';
const ADD_CATEGORY = 'הוסף גורם מקצועי נוסף';
const ADD_CATEGORY_HINT = 'למשל: מהנדס חתום, יועץ בטיחות, ממונה אבטחת מידע, מודד מוסמך';

test.use({ storageState: authState('admin') });

test.describe('אשף Onboarding — שלב 3 גורמים מקצועיים קבועים', () => {
  test('טקסטי השלב: כותרת משנה, "איך זה עובד" בשתי פסקאות, שלושת הסוגים והבלוק "הוסף גורם מקצועי נוסף" #0532cb @desktop @prod-safe', async ({ page }) => {
    const server = await mockWizardServer(page, { fresh: true });
    await page.goto('/onboarding');
    await clickAndSaveTaqo(page, server, NEXT);
    await clickAndSaveTaqo(page, server, NEXT);
    const main = page.getByRole('main', { name: 'גורמים מקצועיים קבועים' });
    await expect(main.getByRole('heading', { name: 'גורמים מקצועיים קבועים', level: 1 })).toBeVisible();

    // подзаголовок = Figma 1141:1823
    await expect(main.getByText(LEAD, { exact: true })).toBeVisible();

    // «איך זה עובד» — ровно 2 абзаца (Figma 1141:1908 / 1141:1909)
    const how = page.getByRole('complementary', { name: 'איך זה עובד' });
    await expect(how.getByRole('paragraph')).toHaveText([HOW_1, HOW_2]);

    // все три типа видны сразу
    for (const type of ['עורך דין', 'רואה חשבון', 'מורשה חתימה']) {
      await expect(main.getByRole('region', { name: type })).toBeVisible();
    }

    // блок свободной категории (Figma 1230:2101)
    await expect(main.getByRole('button', { name: ADD_CATEGORY, exact: true })).toBeVisible();
    await expect(main.getByText(ADD_CATEGORY_HINT, { exact: true })).toBeVisible();
    expect(server.blockedWrites).toEqual([]);
  });

  test('בשלב 3 שם קטגוריה ריק או רווחים נדחה בהודעה "יש להזין שם קטגוריה" #0532cb @desktop @prod-safe', async ({ page }) => {
    const server = await mockWizardServer(page, { fresh: true });
    await page.goto('/onboarding');
    await clickAndSaveTaqo(page, server, NEXT);
    await clickAndSaveTaqo(page, server, NEXT);
    const main = page.getByRole('main', { name: 'גורמים מקצועיים קבועים' });
    await expect(main.getByRole('region', { name: 'מורשה חתימה' })).toBeVisible();
    const regionsBefore = await main.getByRole('region').count();

    await main.getByRole('button', { name: ADD_CATEGORY, exact: true }).click();
    const input = main.getByRole('textbox', { name: 'שם הקטגוריה' });
    const add = main.getByRole('button', { name: 'הוספה', exact: true });
    await add.click();
    await expect(main.getByText('יש להזין שם קטגוריה')).toBeVisible();
    await input.fill('   ');
    await add.click();
    await expect(main.getByText('יש להזין שם קטגוריה')).toBeVisible();
    await expect(main.getByRole('region')).toHaveCount(regionsBefore);
    expect(server.blockedWrites).toEqual([]);
  });
});

test.describe('פרופיל החברה — מגע ב-iPhone', () => {
  test('בנגיעה: "•••" ← "הסרה" פותח את חלון "הסרת גורם מקצועי"; "חזרה" לא מוחק, אישור מוחק #0532cb @iphone', async ({ page }) => {
    // Баг Р4.1: в Safari/iPhone меню закрывалось раньше click, окно не открывалось. Нужен именно WebKit + касание (tap).
    // Данные не меняются: удаление перехватывается «сервером в памяти» (на сервер не уходит).
    const server = await mockWizardServer(page);
    await page.goto('/onboarding');
    await page.getByRole('tab', { name: /גורמים מקצועיים קבועים/ }).click();
    const name = 'QA Lawyer';
    const row = page.getByRole('listitem').filter({ hasText: name });
    await expect(row).toHaveCount(1);
    const dialog = page.getByRole('dialog', { name: 'הסרת גורם מקצועי' });

    // не меньше трёх раз (баг воспроизводился 6/6): окно открывается, «חזרה» закрывает без удаления
    for (let i = 0; i < 3; i++) {
      await page.getByRole('button', { name: `פעולות נוספות: ${name}` }).tap();
      await page.getByRole('menuitem', { name: 'הסרה' }).tap();
      await expect(dialog).toBeVisible();
      await expect(dialog).toContainText(name);
      await dialog.getByRole('button', { name: 'חזרה', exact: true }).tap();
      await expect(dialog).toHaveCount(0);
      await expect(row).toHaveCount(1);
    }

    // подтверждение удаляет строку (в памяти теста — на сервер запись не уходит)
    await page.getByRole('button', { name: `פעולות נוספות: ${name}` }).tap();
    await page.getByRole('menuitem', { name: 'הסרה' }).tap();
    await dialog.getByRole('button', { name: 'הסרה', exact: true }).tap();
    await expect(dialog).toHaveCount(0);
    await expect(row).toHaveCount(0);
    await expect.poll(() => server.saves.length).toBeGreaterThan(0);
    expect(server.blockedWrites).toEqual([]);
  });
});
